import { BECH32_CHECKSUM_CONSTANT } from "./constants.mjs";

const GENERATORS = [
  0x3b6a57b2,
  0x26508e6d,
  0x1ea119fa,
  0x3d4233dd,
  0x2a1462b3,
];

export function polymod(values) {
  let checksum = 1;

  for (const value of values) {
    const top = checksum >> 25;
    checksum = ((checksum & 0x1ffffff) << 5) ^ value;

    for (let index = 0; index < GENERATORS.length; index += 1) {
      if (((top >> index) & 1) !== 0) {
        checksum ^= GENERATORS[index];
      }
    }
  }

  return checksum;
}

export function expandHrp(hrp) {
  const highParts = [];
  const lowParts = [];

  for (const character of hrp) {
    const codePoint = character.codePointAt(0);
    highParts.push(codePoint >> 5);
    lowParts.push(codePoint & 31);
  }

  return highParts.concat([0], lowParts);
}

export function verifyChecksum(hrp, data) {
  return polymod(expandHrp(hrp).concat(data)) === BECH32_CHECKSUM_CONSTANT;
}

