export function convertBits(values, fromBits, toBits, shouldPad) {
  let accumulator = 0;
  let bitCount = 0;
  const converted = [];
  const maximumValue = (1 << toBits) - 1;
  const maximumAccumulator = (1 << (fromBits + toBits - 1)) - 1;

  for (const value of values) {
    if (value < 0 || value >> fromBits !== 0) {
      return null;
    }

    accumulator = ((accumulator << fromBits) | value) & maximumAccumulator;
    bitCount += fromBits;

    while (bitCount >= toBits) {
      bitCount -= toBits;
      converted.push((accumulator >> bitCount) & maximumValue);
    }
  }

  if (shouldPad) {
    if (bitCount !== 0) {
      converted.push((accumulator << (toBits - bitCount)) & maximumValue);
    }
  } else if (
    bitCount >= fromBits ||
    ((accumulator << (toBits - bitCount)) & maximumValue) !== 0
  ) {
    return null;
  }

  return converted;
}

