const OPTIONS = ["--a", "--b", "--help"];

function usageLine(programName) {
  return `usage: ${programName} [-h] --a A --b B`;
}

function helpText(programName) {
  return `${usageLine(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n`;
}

function errorResult(programName, message) {
  return {
    type: "error",
    text: `${usageLine(programName)}\n${programName}: error: ${message}\n`,
  };
}

function resolveLongOption(optionText) {
  const matches = OPTIONS.filter((option) => option.startsWith(optionText));
  return matches.length === 1 ? matches[0] : null;
}

function looksLikeOption(value) {
  if (value === undefined || value === "-") {
    return false;
  }
  if (/^-\d/.test(value) || /^-\.\d/.test(value)) {
    return false;
  }
  return value.startsWith("-");
}

export function parseCliArguments(argv, programName) {
  const parsed = { a: undefined, b: undefined };
  const unrecognized = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === "--") {
      unrecognized.push(...argv.slice(index + 1));
      break;
    }

    if (token === "-h") {
      return { type: "help", text: helpText(programName) };
    }

    if (token.startsWith("--")) {
      const equalsIndex = token.indexOf("=");
      const optionText = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
      const option = resolveLongOption(optionText);

      if (option === null) {
        unrecognized.push(token);
        continue;
      }

      if (option === "--help") {
        if (equalsIndex !== -1) {
          return errorResult(
            programName,
            `argument -h/--help: ignored explicit argument '${token.slice(equalsIndex + 1)}'`,
          );
        }
        return { type: "help", text: helpText(programName) };
      }

      if (equalsIndex !== -1) {
        parsed[option.slice(2)] = token.slice(equalsIndex + 1);
        continue;
      }

      const value = argv[index + 1];
      if (value === undefined || looksLikeOption(value)) {
        return errorResult(programName, `argument ${option}: expected one argument`);
      }

      parsed[option.slice(2)] = value;
      index += 1;
      continue;
    }

    unrecognized.push(token);
  }

  const missing = [];
  if (parsed.a === undefined) {
    missing.push("--a");
  }
  if (parsed.b === undefined) {
    missing.push("--b");
  }

  if (missing.length !== 0) {
    return errorResult(
      programName,
      `the following arguments are required: ${missing.join(", ")}`,
    );
  }

  if (unrecognized.length !== 0) {
    return errorResult(
      programName,
      `unrecognized arguments: ${unrecognized.join(" ")}`,
    );
  }

  return { type: "run", args: parsed };
}

