import { CHECKSUM_LENGTH, MAX_ADDRESS_LENGTH } from "./constants.mjs";
import { verifyChecksum } from "./checksum.mjs";
import { decodeCharsetValues } from "./charsetValues.mjs";
import { convertBits } from "./bitConversion.mjs";

function hasPortableCharacterRange(address) {
  for (const character of address) {
    const codePoint = character.codePointAt(0);
    if (codePoint < 33 || codePoint > 126) {
      return false;
    }
  }
  return true;
}

export function decodeBech32Address(address) {
  if (!hasPortableCharacterRange(address)) {
    return null;
  }

  const allLowercase = address === address.toLowerCase();
  const allUppercase = address === address.toUpperCase();
  if (!allLowercase && !allUppercase) {
    return null;
  }

  const normalizedAddress = address.toLowerCase();
  const separatorIndex = normalizedAddress.lastIndexOf("1");

  if (
    separatorIndex < 1 ||
    separatorIndex + 7 > normalizedAddress.length ||
    normalizedAddress.length > MAX_ADDRESS_LENGTH
  ) {
    return null;
  }

  const hrp = normalizedAddress.slice(0, separatorIndex);
  const dataWithChecksum = decodeCharsetValues(
    normalizedAddress.slice(separatorIndex + 1),
  );

  if (dataWithChecksum === null || !verifyChecksum(hrp, dataWithChecksum)) {
    return null;
  }

  return {
    hrp,
    data: dataWithChecksum.slice(0, -CHECKSUM_LENGTH),
  };
}

export function decodeSegwitAddress(expectedHrp, address) {
  const decoded = decodeBech32Address(address);

  if (decoded === null || decoded.hrp !== expectedHrp) {
    return null;
  }

  const version = decoded.data[0];
  const program = convertBits(decoded.data.slice(1), 5, 8, false);

  if (program === null || program.length < 2 || program.length > 40) {
    return null;
  }

  if (version > 16) {
    return null;
  }

  if (version === 0 && program.length !== 20 && program.length !== 32) {
    return null;
  }

  return [version, program];
}

