import { parseCliArguments } from "./lib/cliArguments.mjs";
import { decodeSegwitAddress } from "./lib/addressDecoder.mjs";
import { formatDecodeResult } from "./lib/pythonFormatting.mjs";

function programNameFromArgv(argv) {
  const scriptPath = argv[1] ?? "test5.mjs";
  const parts = scriptPath.split(/[\\/]/);
  return parts[parts.length - 1] || "test5.mjs";
}

function main() {
  const programName = programNameFromArgv(process.argv);
  const parsed = parseCliArguments(process.argv.slice(2), programName);

  if (parsed.type === "help") {
    process.stdout.write(parsed.text);
    return 0;
  }

  if (parsed.type === "error") {
    process.stderr.write(parsed.text);
    return 2;
  }

  const result = decodeSegwitAddress(parsed.args.a, parsed.args.b);
  process.stdout.write(`${formatDecodeResult(result)}\n`);
  return 0;
}

process.exitCode = main();

